impl flatbuffers::Verifiable for Instruction<'_> {
  #[inline]
  fn run_verifier(
    v: &mut flatbuffers::Verifier, pos: usize
  ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
    use self::flatbuffers::Verifiable;
    v.visit_table(pos)?
     .visit_union::<InstructionValue, _>("value_type", Self::VT_VALUE_TYPE, "value", Self::VT_VALUE, true, |key, v, pos| {
        match key {
          InstructionValue::ValueInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<ValueInstruction>>("InstructionValue::ValueInstruction", pos),
          InstructionValue::AnyInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<AnyInstruction>>("InstructionValue::AnyInstruction", pos),
          InstructionValue::EqualityInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<EqualityInstruction>>("InstructionValue::EqualityInstruction", pos),
          InstructionValue::OperationInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<OperationInstruction>>("InstructionValue::OperationInstruction", pos),
          InstructionValue::UpdateInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<UpdateInstruction>>("InstructionValue::UpdateInstruction", pos),
          InstructionValue::ReadInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<ReadInstruction>>("InstructionValue::ReadInstruction", pos),
          InstructionValue::RetainInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<RetainInstruction>>("InstructionValue::RetainInstruction", pos),
          InstructionValue::BindInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<BindInstruction>>("InstructionValue::BindInstruction", pos),
          InstructionValue::JoinInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<JoinInstruction>>("InstructionValue::JoinInstruction", pos),
          InstructionValue::CallInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<CallInstruction>>("InstructionValue::CallInstruction", pos),
          InstructionValue::ClosureInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<ClosureInstruction>>("InstructionValue::ClosureInstruction", pos),
          InstructionValue::ExternalInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<ExternalInstruction>>("InstructionValue::ExternalInstruction", pos),
          InstructionValue::OpaqueInstruction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<OpaqueInstruction>>("InstructionValue::OpaqueInstruction", pos),
          _ => Ok(()),
        }
     })?
     .finish();
    Ok(())
  }
}
