  pub fn finish(self) -> flatbuffers::WIPOffset<Instruction<'a>> {
    let o = self.fbb_.end_table(self.start_);
    self.fbb_.required(o, Instruction::VT_VALUE,"value");
    flatbuffers::WIPOffset::new(o.value())
  }
